      {"from":"R174:B_ORDER_BOUNDARY","to":"R175:R174_FIBER_DIRECTION_CORRECTION","relation":"failure_direction_corrected_by","deductive":False},
      {"from":"BR20261008:COMMON_EXPERIENTIAL_CONSTRAINT","to":"R175:HELD_OUT_ORDER_PREDICTION","relation":"instantiated_by","deductive":False},
      {"from":"R174:SHARED_TEMPORAL_COORDINATE","to":"R175:PHYSICAL_TEMPORAL_CHAIN","relation":"scoped_as","deductive":False},
      {"from":"R175:HELD_OUT_ORDER_PREDICTION","to":"R173:FAMILIAR_MINENESS_BOUNDARY","relation":"does_not_close","deductive":False}
