    old_ids = {x["id"] for k in ("nodes","rules","context_links") for x in graph[k] if "id" in x}
    assert all(x["id"] not in old_ids for x in nodes + rules)
    graph["nodes"].extend(nodes); graph["rules"].extend(rules); graph["context_links"].extend(links)
    graph["revision"] = REV
    write(GRAPH, graph)

    amendments = {
      "review":"REVIEW-20261008-03","response":"R175","status":"RESEARCHER_CORRECTION_PENDING_INDEPENDENT_REVIEW",
      "suspended_raw_rules":["r173_history_twin_witness","r173_familiar_mineness_boundary"],
      "effective_replacements":["r175_r173_six_row_effective","r175_r173_history_twin_effective","r175_r173_target_boundary_effective"],
      "qc08":{"accepted":True,"correction":"G=>A on baseline-admitted domain; six semantic rows; explicit TwinDomain required; target distinction retained without eight-way independence."},
      "qc09":{"accepted":True,"correction":"Same Theta_STC/different F_order refutes sufficiency; changed Theta_STC/same F_order only refutes a sensitivity/injectivity claim."},
      "qc10":{"response":"R175 positive conditional held-out temporal-order prediction with independent structures, common map, reversal rival and explicit failure criteria; empirical closure remains open."},
      "source_sha256":note_hash
    }
    write(HERE / "REVIEW_AMENDMENTS.json", amendments)
    ext = {"revision":REV,"parent_revision":PARENT_REV,"new_nodes":nodes,"new_rules":rules,"new_context_links":links,"review_overlay":"REVIEW_AMENDMENTS.json"}
    write(HERE / "MAP_EXTENSION.json", ext)
    checks = [
      ("exact_parent_counts", parent_counts == (554,267,168)),
      ("exact_new_counts", (len(nodes),len(rules),len(links)) == (12,6,5)),
      ("unique_ids", len({x["id"] for x in graph["nodes"]}) == len(graph["nodes"]) and len({x["id"] for x in graph["rules"]}) == len(graph["rules"])),
      ("all_rule_endpoints", all(all(p in {n["id"] for n in graph["nodes"]} for p in r["all_of"]+[r["conclusion"]]) for r in graph["rules"])),
      ("note_hash", sha(note)==note_hash),("model_hash",sha(model)==model_hash),
      ("model_12", json.loads(model.read_text())["checks_passed"]==12),
      ("qc08_twin_explicit", "R175:EXPLICIT_TWIN_DOMAIN" in rules[1]["all_of"]),
      ("qc09_direction_split", "sufficiency" in nodes[5]["statement"].lower() and "sensitivity" in nodes[5]["statement"].lower()),
      ("independent_experience_premise", "independently" in nodes[7]["statement"]),
      ("one_common_map", "one common" in rules[3]["statement"].lower()),
      ("heldout_not_anchor", "untouched" in rules[4]["statement"]),
      ("semantic_residual_retained", "R157:SEMANTIC_RESIDUAL" in rules[5]["all_of"]),
      ("no_report_gate", "report" not in rules[4]["all_of"]),
      ("counts", (len(graph["nodes"]),len(graph["rules"]),len(graph["context_links"]))==(566,273,173))
    ]
    if not all(v for _,v in checks):
        raise AssertionError([n for n, v in checks if not v])
    audit={"revision":REV,"counts":{"nodes":len(graph["nodes"]),"rules":len(graph["rules"]),"context_links":len(graph["context_links"])},"checks":[{"name":n,"pass":v} for n,v in checks],"scope":"Structural and scoped semantic audit; not empirical validation, C1 proof or global theory proof.","graph_sha256":sha(GRAPH),"note_sha256":note_hash,"model_sha256":model_hash}
    write(HERE / "MAP_AUDIT.json", audit)
    proof={"round":"R175","items":[
      {"id":"R175-A","claim":"Finite-chain betweenness maps are exactly increasing or decreasing.","premises":["equal finite strict chains n>=3","bijection preserves and reflects betweenness"],"proof":"Endpoint/rank proof in §3","counterexample_boundary":"Without chain/betweenness assumptions other maps may exist.","status":"PROVED_ON_DECLARED_CLASS"},
      {"id":"R175-B","claim":"Common oriented endpoint anchors force the held-out middle experienced-order relation.","premises":["R175-A","one common same-token map","independent endpoint anchors","held-out relation not fitted"],"proof":"Reversal elimination in §4","counterexample_boundary":"No anchors leaves two rivals; incompatible anchors leave no map.","status":"PROVED_CONDITIONALLY"},
      {"id":"R175-C","claim":"QC-08 eight-way wording is unsupported on the baseline-admitted domain.","premises":["baseline trajectory admitted","AgencyLoop contains actual action production"],"proof":"G=>A; explicit six-row models","counterexample_boundary":"Other Avail conventions must be separately declared.","status":"EFFECTIVE_SCOPE_CORRECTION_PENDING_REVIEW"}
    ]}
    write(HERE / "PROOF_LEDGER.json", proof)
    sources={"round":"R175","items":[
      {"id":"S1","source":"UCT A/I v1.2 and R157","use":"C1 transport and semantic residual","scope":"Pinned internal primary theory source."},
      {"id":"S2","source":"R173/R174/BR20261008 and REVIEW-20261008-03","use":"Target contracts, route boundary, joint-map theorem and review corrections","scope":"Exact saved repository sources."},
      {"id":"S3","source":"Kleiner 2024, Consciousness and Cognition 119:103653","use":"Independent phenomenal-structure and bare-isomorphism challenge","scope":"As pinned/read in BR20261008; not evidence for C1."},
      {"id":"S4","source":"Aldé 2026, Synthese 207:204","use":"Similarity geometry does not by itself fix specific phenomenal content","scope":"As pinned/read in BR20261008; not a temporal-order experiment."}
    ],"novelty":"Classical finite-order mathematics is not claimed new; project contribution is typed integration and held-out criterion."}
    write(HERE / "SOURCE_LEDGER.json", sources)
    gaps={"round":"R175","record_type":"RESEARCH_SELF_CHECK_NOT_INDEPENDENT_REVIEW","items":[
      {"id":"R175-G1","severity":"HIGH","location":"§2 experiential admission","impact":"Blocks actual B_order application.","counterexample":"E is copied from the physical chain or defined by the report used as outcome.","repaired":"Independence firewall and pre-registration requirement.","unresolved":"No actual independently grounded same-token experiential chain.","status":"OPEN"},
      {"id":"R175-G2","severity":"HIGH","location":"§2 physical chain","impact":"Blocks actual route grounding.","counterexample":"Stored timestamps or correct answers without executed shared comparison/use.","repaired":"Requires one actual Theta_STC-type route and nonreport consumer.","unresolved":"No actual human/hardware path instance.","status":"OPEN"},
      {"id":"R175-G3","severity":"HIGH","location":"§4 anchors","impact":"Can make the held-out prediction circular.","counterexample":"Endpoint anchors are chosen after seeing the middle target or from different tokens.","repaired":"Common-map, frozen-anchor and held-out clauses.","unresolved":"No implemented blinded protocol.","status":"OPEN"},
      {"id":"R175-G4","severity":"MEDIUM","location":"§3 relation choice","impact":"Betweenness may be too weak or wrong for actual experienced time.","counterexample":"Nonlinear, cyclic or incomparable experiential temporal structure.","repaired":"No generalization beyond the admitted finite chain.","unresolved":"Appropriate experiential relation remains empirical/phenomenological.","status":"OPEN"},
      {"id":"R175-G5","severity":"HIGH","location":"QC-08--10","impact":"Reviewer closure and empirical content remain unavailable.","counterexample":"Self-declared PASS cannot close QC items.","repaired":"Explicit response, overlay and conditional positive prediction.","unresolved":"QC-08/09/10 await independent reviewer assessment.","status":"OPEN"},
      {"id":"R175-G6","severity":"MEDIUM","location":"C1 attachment","impact":"Selected mapping may not extend to the complete K-isomorphism.","counterexample":"Unique selected map conflicts with omitted complete relations.","repaired":"Actual restriction and extension premise retained.","unresolved":"No complete actual instance.","status":"OPEN"}
    ]}
    write(HERE / "GAP_LEDGER.json", gaps)
    print(json.dumps({"revision":REV,"counts":audit["counts"],"checks":len(checks),"graph_sha256":audit["graph_sha256"]}))


